1	<script lang="ts">
2		import { onMount } from 'svelte'
3		import { page } from '$app/state'
4		import { Badge, LiveDot, MoodMarker, SectionHeader } from '$lib/ui'
5		import {
6			LIVE_STATES,
7			dispositionLabel,
8			durationLabel,
9			durationSeconds,
10			formatClock,
11			formatDayLabel,
12			lastCallSummary,
13			moodView,
14			type LastCallSummary
15		} from '$lib/today/model'
16		import { historyHref, parseTParam, parseTurns, type TurnView } from './model'
17	
18		let { data } = $props()
19	
20		const FALLBACK_ZONE = 'Asia/Kolkata'
21	
22		let now = $state(new Date())
23	
24		const rows = $derived(data.rows)
25		const zone = $derived(rows?.profile?.timezone || FALLBACK_ZONE)
26		const transcriptsByRun = $derived(new Map((rows?.transcripts ?? []).map((row) => [row.call_run_id, row])))
27		const resultsByRun = $derived(new Map((rows?.results ?? []).map((row) => [row.call_run_id, row])))
28		const requestedRun = $derived(page.url.searchParams.get('run'))
29		const requestedT = $derived(parseTParam(page.url.searchParams.get('t')))
30		const expandedId = $derived.by(() => {
31			const runs = rows?.runs ?? []
32			if (requestedRun && runs.some((run) => run.id === requestedRun)) return requestedRun
33			return runs[0]?.id ?? null
34		})
35	
36		type RunView = {
37			id: string
38			day: string
39			meta: string
40			moodLabel: string
41			moodNone: boolean
42			live: boolean
43			noConnection: boolean
44			hasResult: boolean
45			summary: LastCallSummary
46			short: string
47			turns: TurnView[]
48		}
49	
50		const views = $derived.by((): RunView[] => {
51			if (!rows) return []
52			return rows.runs.map((run) => {
53				const transcript = transcriptsByRun.get(run.id)
54				const result = resultsByRun.get(run.id)
55				const summary = lastCallSummary(run, rows.mentions, rows.commitments, result?.structured ?? null, zone, now)
56				const duration = durationLabel(durationSeconds(transcript?.raw))
57				const mood = moodView(run)
58				const live = (LIVE_STATES as readonly string[]).includes(run.state)
59				const noConnection = run.disposition === 'not_answered' || run.state === 'failed'
60				const at = formatClock(run.dispatched_at ?? run.scheduled_for, zone)
61				const disposition = dispositionLabel(run.disposition)
62				const meta = live
63					? 'On the call'
64					: [at, duration, disposition].filter(Boolean).join(' · ')
65				const parts: string[] = []
66				if (summary.retired > 0) parts.push(summary.retired === 1 ? 'Retired 1' : `Retired ${summary.retired}`)
67				if (summary.committed > 0) parts.push(summary.committed === 1 ? 'Committed 1' : `Committed ${summary.committed}`)
68				if (summary.captured > 0) parts.push(summary.captured === 1 ? 'Captured 1' : `Captured ${summary.captured}`)
69				const short = live
70					? 'On the call.'
71					: noConnection
72						? 'The call did not connect.'
73						: parts.length > 0
74							? parts.join(' · ')
75							: 'Nothing new'
76				return {
77					id: run.id,
78					day: formatDayLabel(run.dispatched_at ?? run.scheduled_for, zone),
79					meta,
80					moodLabel: mood.label,
81					moodNone: mood.none,
82					live,
83					noConnection,
84					hasResult: result?.valid ?? false,
85					summary,
86					short,
87					turns: parseTurns(transcript?.turns)
88				}
89			})
90		})
91	
92		const hero = $derived(views[0] ?? null)
93		const earlier = $derived(views.slice(1))
94	
95		function isMarked(view: RunView, turn: TurnView): boolean {
96			return view.id === expandedId && requestedT !== null && turn.offsetSeconds === requestedT
97		}
98	
99		$effect(() => {
100			if (requestedT === null || !expandedId) return
101			document.querySelector('[data-turn-mark="true"]')?.scrollIntoView({ block: 'center' })
102		})
103	
104		onMount(() => {
105			const clock = setInterval(() => (now = new Date()), 30_000)
106			return () => clearInterval(clock)
107		})
108	</script>
109	
110	<svelte:head><title>History · Orma</title></svelte:head>
111	{#snippet detail(view: RunView)}
112		<section class="call" aria-label={`Call on ${view.day}`}>
113			<div class="titles">
114				<div class="row top">
115					<span class="title">{view.day}</span>
116					<MoodMarker label={view.moodLabel} none={view.moodNone} />
117				</div>
118				<span class="muted meta">{view.meta}</span>
119			</div>
120			{#if view.live}
121				<div class="row live-head"><LiveDot /><span class="label brand">On the call</span></div>
122				<p class="hint">Nothing to do here. The transcript lands once the call ends.</p>
123			{:else}
124				<div class="row tags">
125					<Badge>retired {view.summary.retired}</Badge><Badge>committed {view.summary.committed}</Badge><Badge>captured {view.summary.captured}</Badge><Badge>mentions {view.summary.mentionCount}</Badge>
126				</div>
127				{#if view.noConnection}
128					<p class="muted">The call did not connect.</p>
129				{/if}
130				{#if view.summary.lines.length > 0}
131					<div class="lines">
132						{#each view.summary.lines as line, index (index)}
133							<div class="row line">
134								<span class="label line-label">{line.label}</span>
135								<span class="line-text">{line.text}</span>
136								{#if line.offset}
137									<a class="mono" href={historyHref(view.id, line.offsetSeconds)}>{line.offset}</a>
138								{/if}
139							</div>
140						{/each}
141					</div>
142				{:else if !view.noConnection && view.hasResult}
143					<p class="muted">Nothing was retired, promised or captured on this call.</p>
144				{/if}
145				{#if !view.hasResult}
146					<p class="muted">Orma did not write anything down from this call.</p>
147				{/if}
148				{#if view.turns.length > 0}
149					<div class="transcript">
150						{#each view.turns as turn, index (index)}
151							{@const marked = isMarked(view, turn)}
152							<div class="turn" class:mark={marked} data-turn-mark={marked ? 'true' : null}>
153								{#if turn.offset}
154									<a class="mono" href={historyHref(view.id, turn.offsetSeconds)}>{turn.offset}</a>
155								{:else}
156									<span class="mono muted">—</span>
157								{/if}
158								<span class="who">{turn.who}</span><span>{turn.text}</span>
159							</div>
160						{/each}
161					</div>
162				{/if}
163			{/if}
164		</section>
165	{/snippet}
166	
167	<main class="history">
168		{#if data.error || !rows}
169			<section class="head">
170				<h1>History</h1>
171				<p class="hint" role="alert">{data.error || 'Could not load your history.'}</p>
172			</section>
173		{:else if views.length === 0}
174			<section class="head">
175				<h1>History</h1>
176				<p class="gloss">Every call, newest first. Mood is what the call heard.</p>
177			</section>
178			<section><p class="muted">No calls yet. Your finished calls will land here, newest first.</p></section>
179		{:else}
180			<section class="head">
181				<h1>History</h1>
182				<p class="gloss">Every call, newest first. Mood is what the call heard.</p>
183			</section>
184	
185			{#if hero}
186				{@const open = hero.id === expandedId}
187				{#if open}
188					{@render detail(hero)}
189				{:else}
190					<section class="call">
191						<a class="rowlink" href={historyHref(hero.id)}>
192							<span class="copy">
193								<span class="row-day">{hero.day}</span>
194								<span class="row meta">{hero.meta} <MoodMarker label={hero.moodLabel} none={hero.moodNone} /></span>
195								<span class="line-text">{hero.short}</span>
196							</span>
197							<span class="muted" aria-hidden="true"><svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M6 3.5l4.5 4.5L6 12.5"></path></svg></span>
198						</a>
199					</section>
200				{/if}
201			{/if}
202	
203			{#if earlier.length > 0}
